mapper.select:
/* BmsLocalInspectResultMapper.selectBmsLocalInspectResultByBlNo  : 특송창고 검사결과 조회 */
SELECT 
	*
FROM TB_BMS_LOCAL_INSPECT_RESULT
WHERE 1=1


		AND IN_NO = #{inNo}


		AND BL_NO = #{blNo}

/* BmsLocalInspectResultMapper.selectBmsInDetailByBlNo : 반입 BL조회(반출,홀드 포함) */ SELECT tbi.IN_NO , tbi.CUSTOMS_REPORT_NO , CONVERT(CHAR(19), tbi.LAST_POD_DATE , 20) AS LAST_POD_DATE , tbi.LAST_POD_STATUS , tbi.LAST_POD_5TL_STATUS , CONVERT(CHAR(19), tbi.LAST_POD_RAQ_DATE , 20) AS LAST_POD_RAQ_DATE , tbi.LAST_POD_R48_DATE , tbi.IN_CLASS , tbi.IN_APPROVAL_NO , tbi.OD_JOB_NO , tbi.IN_PLAN_NO , tbi.CARGO_REFERENCE_NO , tbi.BL_NO , tbi.MBL_NO , tbi.CD_TYPE , tbi.ECM_TYPE , tbi.CD_USE_TYPE , tbi.BIG_SIZE_YN , tbi.XRAY_SCAN_CT , tbi.XRAY_IMAGE_CT , tbi.AR_DATE , tbi.AR_TIME , tbi.COMMODITY_ITEM_LOC , tbi.SHIPPER_CODE , tbi.SHIPPER_NAME , tbi.CONSIGNEE_CODE , tbi.CONSIGNEE_NAME , tbi.NOTIFY_CODE , tbi.NOTIFY_NAME , tbi.CARRYIN_DATE , tbi.OUT_NOTICE_DATE , tbi.PERIOD_OVER_DATE , tbi.CUSTOMER_CODE , tbi.CUSTOMER_NAME , tbi.CT , tbi.WT , tbi.CBM , tbi.DELIVERY_CODE , tbi.DELIVERY_NAME , (tbi.CT - ISNULL(tbo.S_OUT_CT, 0)) AS STOCK_CT , (tbi.WT - ISNULL(tbo.S_OUT_WT, 0)) AS STOCK_WT , oh.CARRYIN_STOP_YN , oh.CARRYOUT_STOP_YN , oh.HOLD_DATE , oh.HOLD_CODE , oh.HOLD_REASON , oh.HOLD_RELEASE_YN , oh.HOLD_RELEASE_ATTN , oh.HOLD_RELEASE_DATE FROM TB_BMS_IN tbi WITH (NOLOCK) LEFT JOIN ( SELECT '' AS HOLD_YN , MAX(OD_JOB_NO) AS OD_JOB_NO , MAX(HOLD_CODE) AS HOLD_CODE , MAX(HOLD_REASON) AS HOLD_REASON , MAX(HOLD_RELEASE_YN) AS HOLD_RELEASE_YN , MAX(HOLD_RELEASE_ATTN) AS HOLD_RELEASE_ATTN , MAX(HOLD_RELEASE_DATE) AS HOLD_RELEASE_DATE , MAX(HOLD_DATE) AS HOLD_DATE , MAX(CARRYIN_STOP_YN) AS CARRYIN_STOP_YN , MAX(CARRYOUT_STOP_YN) AS CARRYOUT_STOP_YN FROM TB_ECM_OD_HOLD GROUP BY OD_JOB_NO ) AS oh ON oh.OD_JOB_NO = tbi.OD_JOB_NO LEFT JOIN ( SELECT IN_NO , SUM(OUT_CT) AS S_OUT_CT , SUM(OUT_WT) AS S_OUT_WT FROM TB_BMS_OUT WITH (NOLOCK) GROUP BY IN_NO ) AS tbo ON tbo.IN_NO = tbi.IN_NO WHERE 1=1
AND tbi.IN_NO = #{inNo}
AND tbi.BL_NO = #{blNo}

/* BmsLocalInspectResultMapper.selectOneBmsOutPlan  : 반출 상세 조회 */
SELECT 
	*
FROM TB_BMS_OUT_PLAN WITH (NOLOCK)
WHERE 1=1


		AND IN_NO = #{inNo}


		AND BL_NO = #{blNo}

mapper.update:
/* BmsLocalInspectResultMapper.updateBmsLocalInspectResult  : 특송창고 검사결과 반출확인업데이트 */
UPDATE TB_BMS_LOCAL_INSPECT_RESULT
SET
    TIC_OUT_SCAN_DATE_TIME = GETDATE(),
	TIC_OUT_SCAN_USER_ID   = #{updateUserId}
WHERE BL_NO = #{blNo}

/* BmsLocalInspectResultMapper.updateBmsTicComebackLocalInspectResult  : 특송창고 검사결과 반입입고확인 업데이트 */
UPDATE TB_BMS_LOCAL_INSPECT_RESULT
SET
    TIC_COME_BACK_SCAN_DATE_TIME = GETDATE(),
	TIC_COME_BACK_SCAN_USER_ID   = #{updateUserId}
WHERE BL_NO = #{blNo}

mapper.select:
		/* BmsLocalInspectResultMapper.selectMblList  : 반입날자 범위에 해당하는 MBL번호들을 조회 */
		SELECT
			*
		FROM TB_BMS_LOCAL_INSPECT_RESULT
		WHERE CARRYIN_DATE >= CONVERT(VARCHAR, DATEADD(DAY, -1, GETDATE()), 23)
            AND CARRYIN_DATE <= CONVERT(VARCHAR, GETDATE(), 23);

/* BmsLocalInspectResultMapper.getSelectedInspectResultList  : 선택한 검사결과 리스트를 조회한다 */
SELECT 
	*
FROM TB_BMS_LOCAL_INSPECT_RESULT
WHERE IN_NO IN (
	#{item.inNo}
)

mapper.update:
/* BmsLocalInspectResultMapper.updateInspectionFinishedYn  : 검사결과의 검사완료여부 업데이트 */
UPDATE TB_BMS_LOCAL_INSPECT_RESULT
SET 
	INSPECTION_FINISH_YN	=	#{yn}
WHERE IN_NO = #{inNo}

mapper.select:
/* BmsLocalInspectResultMapper.selectBmsInByInNo  : pod에 입력할 OD_JOB_NO참조를 위해서 반입을 조회한다 */
SELECT 
	*
FROM TB_BMS_IN WITH (NOLOCK)
WHERE IN_NO = #{inNo}
